const APP_HTML_B64 = "";

// atob() decodes base64 into a "binary string" where each character is one
// raw byte (0-255) — it is NOT a UTF-8-aware decode. The app's HTML is full
// of multi-byte UTF-8 characters (→, —, ·, curly quotes), so calling
// atob() directly and serving the result corrupts every one of them: each
// original UTF-8 byte gets treated as its own Latin-1 character, then
// re-encoded as UTF-8 again when the Response is sent, doubling the bytes
// into mojibake (this is exactly the "â??" garbage baked into exported
// videos). Decoding through a Uint8Array + TextDecoder keeps the real
// UTF-8 bytes intact.
function decodeBase64Utf8(b64) {
  const binaryString = atob(b64);
  const bytes = Uint8Array.from(binaryString, c => c.charCodeAt(0));
  return new TextDecoder('utf-8').decode(bytes);
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const cors = {
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "GET,POST,OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type"
    };

    // GET /  -> serve the app itself over a real https:// URL (not file://),
    // since Puter.js refuses to run when the page is opened as a local file.
    if (url.pathname === "/" || url.pathname === "/app") {
      const html = decodeBase64Utf8(APP_HTML_B64);
      return new Response(html, {
        headers: { ...cors, "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store, no-cache, must-revalidate" }
      });
    }

    // handle the browser's CORS preflight check
    if (request.method === "OPTIONS") {
      return new Response(null, { headers: cors });
    }

    // GET /voices  -> no external service needed anymore; MeloTTS (Workers AI)
    // has one built-in voice per language rather than ElevenLabs' named
    // voice library, so we just report a single free voice here. This keeps
    // the client's existing voice-list UI working without changes.
    if (url.pathname === "/voices") {
      return new Response(JSON.stringify({
        voices: [
          { voice_id: "default-en", name: "Default Voice (Free — Workers AI)" }
        ]
      }), { headers: { ...cors, "Content-Type": "application/json" } });
    }

    // POST /tts/<voiceId>  -> generate narration audio for one scene using
    // Workers AI's free MeloTTS model instead of ElevenLabs. voiceId is
    // accepted for compatibility with the existing client code but is
    // otherwise unused, since MeloTTS has one voice per language rather
    // than a named voice library.
    if (url.pathname.startsWith("/tts/")) {
      try {
        const payload = await request.json();
        const text = payload.text || "";
        if (!text.trim()) {
          return new Response(JSON.stringify({ error: "No text provided for narration." }), {
            status: 400,
            headers: { ...cors, "Content-Type": "application/json" }
          });
        }

        // MeloTTS has a known, ongoing issue on Cloudflare's side (error
        // 3043) as of this writing. Retry a few times with a short delay,
        // since these platform errors are sometimes intermittent even
        // during an outage — this costs nothing extra if the first
        // attempt succeeds.
        let result;
        let lastErr;
        for (let attempt = 1; attempt <= 3; attempt++) {
          try {
            result = await env.AI.run("@cf/myshell-ai/melotts", {
              prompt: text,
              lang: "en"
            });
            lastErr = null;
            break;
          } catch (e) {
            lastErr = e;
            if (attempt < 3) await new Promise(r => setTimeout(r, 800 * attempt));
          }
        }
        if (lastErr) throw lastErr;

        // MeloTTS returns { audio: "<base64-encoded mp3>" }
        const binaryString = atob(result.audio);
        const bytes = new Uint8Array(binaryString.length);
        for (let i = 0; i < binaryString.length; i++) {
          bytes[i] = binaryString.charCodeAt(i);
        }

        return new Response(bytes, {
          headers: { ...cors, "Content-Type": "audio/mpeg" }
        });
      } catch (err) {
        return new Response(JSON.stringify({ error: String(err && err.message || err) }), {
          status: 500,
          headers: { ...cors, "Content-Type": "application/json" }
        });
      }
    }

    // POST /analyze  -> ask a free Cloudflare Workers AI model to storyboard the source text
    if (url.pathname === "/analyze") {
      try {
        const payload = await request.json();
        const systemPrompt = payload.system || "";
        const userMessage = payload.messages?.[0]?.content || "";

        const aiResp = await env.AI.run("@cf/meta/llama-3.3-70b-instruct-fp8-fast", {
          messages: [
            { role: "system", content: systemPrompt },
            { role: "user", content: userMessage }
          ],
          // FIX: without max_tokens, the model was hitting the default output
          // limit and getting cut off mid-JSON, which broke JSON.parse() on
          // the client ("Unterminated string in JSON..."). Raised it so the
          // full storyboard can be returned without truncation.
          max_tokens: 8000,
          temperature: 0.4
        });

        // Workers AI usually returns aiResp.response as a plain string, but
        // has been observed returning an object instead. Coerce it to a
        // real string here so the client always gets valid, parseable text
        // (previously an object would silently become "[object Object]"
        // on the client side and break JSON.parse).
        const text = typeof aiResp.response === "string"
          ? aiResp.response
          : JSON.stringify(aiResp.response || aiResp);
        return new Response(JSON.stringify({ content: [{ type: "text", text }] }), {
          headers: { ...cors, "Content-Type": "application/json" }
        });
      } catch (err) {
        return new Response(JSON.stringify({ error: String(err && err.message || err) }), {
          status: 500,
          headers: { ...cors, "Content-Type": "application/json" }
        });
      }
    }

    // POST /generate-image -> real AI-generated character art via Cloudflare
    // Workers AI's free image model (same account/quota as /analyze — no
    // separate signup, no card). Used for Story Mode's persistent character
    // portraits. The binding returns the image as raw bytes directly (per
    // Cloudflare's own docs for this model), so it's passed straight through
    // as the response body rather than unwrapped from a JSON envelope.
    if (url.pathname === "/generate-image") {
      try {
        const payload = await request.json();
        const prompt = (payload.prompt || "").slice(0, 800);
        if (!prompt.trim()) {
          return new Response(JSON.stringify({ error: "No prompt provided for image generation." }), {
            status: 400,
            headers: { ...cors, "Content-Type": "application/json" }
          });
        }
        const result = await env.AI.run("@cf/bytedance/stable-diffusion-xl-lightning", {
          prompt,
          num_steps: 6,
          width: 768,
          height: 768
        });
        return new Response(result, {
          headers: { ...cors, "Content-Type": "image/jpeg" }
        });
      } catch (err) {
        return new Response(JSON.stringify({ error: String(err && err.message || err) }), {
          status: 500,
          headers: { ...cors, "Content-Type": "application/json" }
        });
      }
    }

    // TEMPORARY: GET /debug -> shows key shape only, not the full value. Remove after troubleshooting.
    if (url.pathname === "/debug") {
      const k = env.ELEVENLABS_API_KEY || "";
      const a = env.ANTHROPIC_API_KEY || "";
      return new Response(JSON.stringify({
        elevenlabs: {
          length: k.length,
          starts_with: k.slice(0, 6),
          ends_with: k.slice(-4)
        },
        anthropic: {
          length: a.length,
          starts_with: a.slice(0, 8),
          ends_with: a.slice(-4)
        }
      }), { headers: { ...cors, "Content-Type": "application/json" } });
    }

    return new Response("Not found", { status: 404, headers: cors });
  }
};
